const levels=[0,50000,100000,200000,400000].map((min,i)=>({id:'LV'+i,name:gradeNames[i],min,max:[50000,100000,200000,400000,null][i],multiplier:[1,1.5,1.8,2,3][i],annual:[1,2,5,8,12][i],validity:i?'12个月':'长期有效'}));
const categories=[['direct','产品直降券'],['subsidy','全民补贴券'],['domestic','国内专属补贴券'],['base','常规会员基础券'],['boost','会员尊享加码券']];
const pricingTypes=[['fixed','直减券'],['percent','折扣券'],['bundle','按人优惠'],['perPerson','按人直减']];
function couponPricingMethods(t){return [...new Set(t.tiers.map(r=>pricing(r).method))];}
function couponPricingLabel(t){return couponPricingMethods(t).map(method=>pricingTypes.find(x=>x[0]===method)?.[1]||method).join('／');}
function tiers(type){let rows;if(type==='standard')rows=[{threshold:10000,amount:100,points:0,product:100,channel:0,supplier:0}];if(type==='direct')rows=[200,500,1000,1500,5000].map((x,i)=>({threshold:0,amount:x,points:0,product:x,channel:0,supplier:0,perPerson:true,scope:i===4?'晟和邮轮':'自营、甄选'}));if(type==='subsidy')rows=[10000,20000,40000,60000].map(x=>({threshold:x,amount:x*.01,points:0,product:0,channel:x*.01,supplier:0}));if(type==='domestic')rows=[{threshold:5000,amount:50,points:0,product:0,channel:50,supplier:0}];if(type==='base')rows=[10000,20000,40000,60000].map(x=>({threshold:x,amount:x*.015,points:x*.15,product:x*.015,channel:0,supplier:0}));if(type==='boost')rows=[[1500,10000,250],[1500,20000,350],[1500,40000,550],[1500,60000,750],[3000,20000,500],[3000,40000,700],[3000,60000,900],[6000,40000,1000],[6000,60000,1200],[9000,60000,1500]].map(([points,threshold,amount])=>({points,threshold,amount,product:points/10,channel:threshold*.01,supplier:0}));return rows.map((r,i)=>Object.assign({id:type+'-'+(i+1),scope:type==='domestic'?'国内自营':'自营、甄选',days:30,total:5000,perUser:1,start:'2026-10-01',end:'2026-12-31'},r));}
function gradeFor(amount,rules=levels){return rules.filter(r=>amount>=Number(r.min)).at(-1)||rules[0];}
function pointsFor(amount,multiplier){const base=Math.round(Number(amount)*.15);const total=Math.round(base*Number(multiplier));return{base,extra:total-base,total};}
function validateLevels(rows){const e=[];if(rows.length!==5)e.push('请保留五个会员等级');rows.forEach((r,i)=>{if(!Number.isFinite(+r.min)||+r.min<0)e.push(r.name+'消费门槛无效');if(i===0&&+r.min!==0)e.push('蓝卡消费起点须为0');if(i&&+rows[i-1].max!==+r.min)e.push('消费区间须连续且不重叠');if(i<4&&(!Number.isFinite(+r.max)||+r.max<=+r.min))e.push(r.name+'上限须大于下限');if(i===4&&r.max!==null&&r.max!=='')e.push('黑钻卡不设消费上限');if(!Number.isFinite(+r.multiplier)||+r.multiplier<1)e.push('积分加速倍数不得低于1');if(!Number.isInteger(+r.annual)||+r.annual<0)e.push('年度活动次数须为非负整数');});return [...new Set(e)];}
function validateTiers(type,rows,allocations,pointsExchange){const e=[];if(type==='standard'&&rows.some(r=>+r.points>0)&&rows.some(r=>!(+r.points>0)))e.push('同一券模板的档位须统一为免费领取或积分兑换');rows.forEach(r=>{try{validatePricing(r,type);validateValidity(r);}catch(error){e.push(error.message);}if(+r.threshold<0)e.push('订单门槛不能为负数');if((pointsExchange??['base','boost'].includes(type))&&(!Number.isInteger(+r.points)||+r.points<=0))e.push('兑换积分须为正整数');if(!allocations&&Math.abs((+r.product||0)+(+r.channel||0)+(+r.supplier||0)-(+r.amount))>.001)e.push('承担金额合计必须等于优惠金额');if(type==='domestic'&&(+r.amount>50||+r.threshold!==5000))e.push('国内券满5000减50，封顶50元');if(!allocations&&type==='direct'&&+r.channel!==0)e.push('产品直降券由产品或供应商承担');if(!allocations&&['subsidy','domestic'].includes(type)&&(+r.product!==0||+r.supplier!==0))e.push('补贴券固定渠道端承担');if(r.validityMode!=='fixed'&&(+r.days<1||!Number.isInteger(+r.days)))e.push('有效天数须为正整数');});return [...new Set(e)];}
const CHARTER_SOURCE="凯撒旅游会员管理章程\n第一章 总则\n第一条 目的与适用范围\n为感谢每一位选择凯撒旅游的会员，提升会员的服务体验、 促进跨业务消费， 整合凯撒旅游\n集团用户资源， 以积分和权益为核心构建会员体系， 规范会员服务管理， 特制定本章程。 本\n章程适用于所有凯撒旅游会员及使用积分、 权益的用户，旨在为尊敬的会员提供系统性的尊\n享服务指南。请您注册用户或会员，且在使用用户或会员服务前，仔细阅读并理解本章程，\n您的注册、绑定、消费行为视为对本章程内容的理解与接受。\n第二条 定义\n1. 凯撒旅游：指北京凯撒国际旅行社有限责任公司及其旗下直接或间接提供旅游相关\n产品与服务的子公司、分公司、分支机构或关联公司（包括但不限于北京凯撒晟和\n国际旅行社有限公司、北京凯撒亿步国际旅行社有限公司等）的统称。本章程项下\n的会员服务、积分及权益，可能由上述任一主体或多家主体共同提供，相关权利义\n务由实际提供服务的法律主体承担。\n2. 凯撒优选：指由凯撒旅游提供技术支持和运营服务的微信小程序，本章程中提及的\n会员注册、积分获取与使用、权益兑换等行为，均通过该平台进行。\n3. 通通游平台：是凯撒旅游自建并拥有的用于凯撒旅游零售业务、门店业务和供应链\n业务的综合性业务管理系统。\n4. 注册用户：指已在凯撒优选完成手机号验证绑定但尚未进行首次消费的“凯撒优选”\n平台用户。注册用户可浏览平台内容，但无法享受会员积分、等级权益等服务。\n5. 会员（您）：指成功注册并接受本章程， 通过凯撒旅游官方渠道 （限于凯撒优选小程\n序、通通游平台）完成消费且订单对应行程已回团或产品已核销后获得会员身份，\n并依照本章程享有相应会员等级与专属权益的用户。\n6. 积分：指凯撒旅游为奖励会员消费与互动而授予的虚拟奖励工具，其功能、价值及\n有效期均由凯撒旅游单方设定， 具体规则以本章程及凯撒旅游的公布调整规则为准。\n积分可用于凯撒旅游指定的使用场景（如积分商城）兑换指定礼品、优惠券或抵扣\n部分消费金额，不可变现、不可转让、不可赠与，亦不得作为财产进行任何形式的\n交易或继承。凯撒旅游有权根据业务发展及法律法规要求，对积分获取与使用规则\n（包括但不限于积分价值、兑换比例、使用范围等）进行调整，具体以凯撒旅游实\n时公示标准为准。\n7. 权益：指凯撒旅游为不同等级会员提供的差异化优惠或权益服务，包括但不限于积\n分加速、会员专属活动、第三方合作权益等。所有权益均由凯撒旅游免费提供，其\n可获得性、种类、内容及质量可能因时间、地区、合作方情况等因素而变动。部分\n权益数量有限，兑完即止。涉及第三方提供的权益（以下简称“第三方权益”），其\n服务质量与责任由该第三方承担，凯撒旅游协助对接，不对此类权益的质量、可用\n性及任何争议承担保证或连带责任。\n消费金额：指会员通过凯撒旅游的官方渠道（限于凯撒优选、通通游平台）线上下\n单，购买凯撒旅游产品、 服务而实际支付的实付款项金额 （以人民币计算）； 会员如\n\n通过线下手工订单、定制团等非本章程确认的官方渠道或流程支付的订单，不参与\n会员积分与等级评定。旅行团产品消费金额按订单“回团”时间、酒店/机票/门票\n等标准化产品按“核销”时间计入相应会员等级统计周期，具体以本章程或凯撒旅\n游公布的规定为准。\n第三条 会员身份确认\n1. 用户通过凯撒优选小程序完成手机号验证绑定后，即成为注册用户。注册用户通过\n凯撒旅游官方渠道（包括凯撒优选小程序、通通游平台等）完成首笔消费实际接受\n凯撒旅游服务且订单对应行程已回团或产品已核销后，将自动升级为会员。会员身\n份及积分、权益仅授予实际支付订单的客户。\n2. 会员等级由低到高分为蓝卡、银卡、金卡、铂金卡、黑钻卡，仅依据会员近12 个月\n的累计消费金额进行动态评定，具体等级规则以本章程规定为准。\n\n第二章 会员等级与权益\n第四条 会员等级规则\n会员等级 注册用户 蓝卡 银卡 金卡 铂金卡 黑钻卡\n评定标准（年消费） 注册绑定 0-5 万元 5-10 万元 10-20 万元 20-40 万元 ≥40 万元\n基础权益 积分加速 - - 1.5 倍 1.8 倍 2 倍 3 倍\n活动特权 会员活动 - 1 次/年 2 次/年 5 次/年 8 次/年 12 次/年\n注：\n1. 消费金额指订单实际实付金额，旅行产品按回团时间、酒店机票等按核销时间计入\n（不含退费金额）。\n2. 积分加速倍数为在基础积分（消费金额的15%）之上的加速系数。\n第五条 等级权益细则\n1. 积分及积分加速：会员消费可获得积分， 基础积分为消费金额的15%。 各等级会员按\n本章程第四条规定的加速倍数提升积分获取效率。 （示例：黑钻卡会员消费1 万元，\n可获得基础积分1500 积分 × 3.0 = 4500 积分） 。\n2. 活动特权：凯撒旅游将根据会员等级， 不定期定向蓝卡-黑钻卡会员发出邀请，会员\n可参与专属回馈活动 （如高端线路体验、 旅游主题沙龙等） 。 每年各等级会员可受邀\n参与的活动次数上限详见本章程第四条表内规定。\n3. 第三方权益：凯撒旅游可能会不定时为特定等级会员引入由第三方合作方（如航空\n公司、酒店集团、金融机构等）独立提供的增值服务或权益（如机场贵宾厅、客房\n升级、优先登机等） 。 该等权益是凯撒旅游为会员争取的免费、额外增值优惠，并非\n会员依据本章程所必然获得的、或由凯撒旅游直接提供的核心权益。\n3.1.责任限制：凯撒旅游仅作为第三方权益的信息的发布渠道，将会员引导至第三\n方权益。第三方权益的预约、获取、使用条件、服务质量、可用性及最终解释权均\n完全归属于相应的第三方合作方。\n3.2.非保证责任：凯撒旅游不对任何第三方权益的可用性、质量、有效性、安全性\n\n承担任何明示或默示的保证或担保责任。会员因使用或无法使用第三方权益而产生\n的任何争议、损失或损害，应直接与第三方合作方解决，凯撒旅游可提供必要协助\n但不承担任何直接或连带责任。\n3.3.变更与终止：第三方权益可能受名额、地域、时间等限制，并可能因合作方政\n策调整而随时变更、中止或终止，凯撒旅游无需为此单独通知每位会员。\n3.4.会员义务：会员在申请和使用第三方权益前，应自行查阅并同意该第三方合作\n方的具体要求、条款与条件及隐私政策。会员在使用第三方权益时，其行为应同时\n遵守本章程及第三方合作方的规则。\n第六条 等级变更说明：\n1. 升级：系统将实时跟踪会员的累计消费金额。 当会员近12 个月累计消费金额达到更\n高等级标准时，系统将在次月 1 日自动为其升级至对应会员等级，并自升级之日起\n享受相应权益。\n2. 保级与降级：每月1 日， 系统将自动对所有会员近12 个月的累计消费金额进行一次\n重新评估，并据此更新会员等级。\n2.1.保级：若消费金额达到或维持当前等级标准，则等级保持不变。\n2.2.降级：若消费金额未达到维持当前等级标准，将降至符合条件的相应等级（有\n历史消费的会员最低降至蓝卡会员） 。\n3. 等级有效期：蓝卡会员永久有效，其他等级会员等级有效期为1 年（自等级达成或\n维持的次月1 日起计算12 个自然月） ；有效期满后， 系统将立即根据您当时近 12 个\n月的累计消费金额，按照本条第2 款规则重新评定等级。\n\n第三章 积分获取与使用规则\n第七条 积分获取方式\n1. 消费积分：\n1.1.基础积分：会员每完成一笔有效消费，可按消费金额*15%计算获得基础积分值\n（例：消费1 万元获1500 积分），积分按四舍五入取整。\n1.2.等级加速积分：银卡、金卡、铂金卡、黑钻卡会员在获取基础积分时，可分别\n享受 1.5 倍-3.0 倍不等的对应等级加速权益，具体以本章程第四条项下标准执行。\n2. 积分计算时间：积分将于消费订单所对应的行程回团或产品核销后，自动发放至会\n员账户。具体而言：\n2.1.旅游套餐、跟团游等产品，按行程结束回团之日起算；\n2.2.酒店、机票、门票、签证等产品，按实际使用或核销之日起算。\n2.3.其他：本章程未列明的其他产品或服务，其积分计算与发放时间将以凯撒旅游\n另行公示的规则为准。凯撒旅游有权根据产品、服务的特性及业务运营需要，合理\n确定积分的入账时间。\n3. 行为积分：会员可通过凯撒优选完成指定的互动行为 （如每日签到、 撰写产品评价、\n分享活动等） ， 可依据凯撒优选当时平台实时公示的规则额外获取积分。 凯撒旅游有\n权随时调整任务内容、积分奖励额度及活动规则，并于凯撒优选公示后生效。\n4. 促销活动积分：凯撒旅游可能在会员权益日、节假日等特定时期，不定期推出促销\n\n活动（如积分翻倍、额外赠分等） 。活动规则、适用范围及有效期以官方公告为准。\n此类活动可能设有积分获取上限或总额限制，先到先得，赠完即止。\n异常情况处理：所有积分的获取必须基于真实、合法的消费和会员互动行为。凯撒\n旅游有权对涉嫌刷单、套现、作弊等违规行为的积分获取进行调查，一经核实，有\n权扣除相应积分、冻结/注销/终止会员账户并追究相关法律责任。\n第八条 积分使用规则\n1. 使用场景\n会员可通过以下方式使用其积分：\n1.1. 抵扣消费： 会员在购买凯撒旅游自营旅游产品时， 可在支付环节使用积分抵扣\n部分订单金额。抵扣标准为：10 积分 = 1 元人民币。每笔订单可使用积分抵扣的金\n额最高不超过该订单金额的2%。\n1.2. 兑换权益： 会员可在凯撒优选的积分商城内， 使用积分兑换指定的商品、 服务\n或权益，包括但不限于旅行优惠券、实物礼品、第三方服务（如机场贵宾厅、航空\n里程等） 。具体兑换比例、库存及规则以积分商城实时公示为准。\n2. 限制条款\n积分使用须遵守以下限制：\n2.1. 通用限制：积分不可兑现、不可转让、不可赠与、不可继承，且仅可用于本章\n程及平台规则指定的场景。\n2.2. 范围限制：积分不可用于支付外采（非凯撒旅游自营）产品、保险、税费、以\n及其他明确标示不可使用积分的费用。\n2.3. 第三方权益： 兑换涉及第三方提供的商品或服务时， 其质量、 可用性及售后服\n务均由该第三方负责，凯撒旅游不承担任何法律责任。相关争议需会员直接与第三\n方解决。\n2.4. 异常使用：凯撒旅游有权监控积分使用行为， 对于涉嫌欺诈、套现、 作弊等异\n常使用行为，有权冻结积分、撤销交易、甚至冻结/注销会员账户。\n3. 积分有效期与清零\n3.1. 有效期：积分自获取之日起生效，有效期为2 年（即730 天）。\n3.2. 清零规则：积分逾期之日满将自动失效并清零（即，自获取积分之日起满730\n天之当日晚 23:59:59 失效）。系统将依据“先获取的积分先使用”的原则自动扣减\n相应积分。\n3.3. 退款处理： 若会员使用积分抵扣或兑换的订单发生全部或部分退款， 已消耗的\n积分将不予退还，退款金额仅为用户实际支付的现金部分。\n3.4. 失效通知： 凯撒旅游可提供积分到期提醒服务 （如通过小程序消息、 短信等） ，\n但此项服务并非凯撒旅游的法定义务，最终积分有效期以系统记录为准。\n\n第四章 会员服务与保障\n第九条 服务承诺\n1. 积分查询：会员可通过凯撒优选实时查询积分余额、获取与消耗明细、有效期等信\n息。\n\n2. 权益兑现：凯撒旅游将通过凯撒优选等官方渠道，确保会员等级权益与活动规则透\n明、公开。对于会员在权益兑现中提出的争议，凯撒旅游客服团队将争取在接到反\n馈后的48 小时内予以响应并启动处理流程。\n3. 数据安全：凯撒旅游将采取符合法律规定的合理途径保护会员的隐私信息，未经会\n员授权同意，不向任何第三方披露、泄露或出售其个人敏感信息，法律法规另有规\n定的除外。\n4. 服务可用性：凯撒旅游将尽力保障会员系统 7×24 小时稳定运行，但鉴于互联网服\n务的特殊性，对于因系统维护、升级、故障、不可抗力等原因导致的服务中断或延\n迟，凯撒旅游不承担相应责任，但将尽力提前公告或在事后予以说明。\n第十条 投诉与纠纷处理\n1. 反馈渠道： 会员可通过以下渠道就积分、 权益、 服务等问题进行咨询、 投诉或反馈：\n1.1.官方客服热线：400-606-66656；\n1.2.凯撒优选小程序在线客服；\n1.3.凯撒旅游线下服务中心；\n1.4.其他：凯撒旅游官方公布的反馈渠道。\n2. 处理流程：\n会员提出争议后，凯撒旅游会员运营部将首先进行核实。经核实，确因凯撒旅游原\n因导致的积分、权益或等级记录错误，将按本章程规则予以补发或修正。\n3. 处理时限：凯撒旅游高度重视会员的反馈， 并致力于在接到投诉后的48 小时内 （工\n作日）提供初步响应；请您理解，对于涉及复杂情况或需要多部门协查的争议，处\n理时间可能适当延长。对于因会员未能提供必要信息、节假日、系统故障、不可抗\n力或其他非因凯撒旅游主观故意或重大过失导致的程序延迟，凯撒旅游不承担相应\n责任。\n4. 最终决定权：所有争议的解决均须以本章程及凯撒旅游平台记录为准。凯撒旅游拥\n有对争议的最终解释与处理决定权。\n\n第五章 会员权利与义务\n第十一条 会员权利\n作为凯撒旅游会员，您享有以下权利：\n1. 公平获取权：在遵守本章程的前提下，公平地获得积分、晋升会员等级及兑换各项\n会员权益的资格。\n2. 知情与咨询权：有权要求凯撒旅游对本章程及会员规则不明确之处进行解释说明；\n有权就账户积分、等级记录异常等情况申请核查。\n3. 权益享受权：有权按照本章程规定享受相应会员等级对应的积分加速、专属活动等\n权益。\n4. 免责声明：所有积分及权益均为凯撒旅游授予会员的优惠与礼遇，并非您支付对价\n后必然获得的固定回报。凯撒旅游可根据业务发展、市场环境及法律法规变化，对\n积分价值、权益内容及规则进行单方调整，并在法律要求的范围内进行公示。因不\n可抗力、第三方原因或您自身原因导致权益无法实现的，凯撒旅游不承担责任。\n\n5. 会员参加凯撒旅游举办的各种沙龙活动或其他联谊、信息交流等活动均采取自愿的\n原则。\n第十二条 会员义务\n作为凯撒旅游会员，您应履行以下义务：\n1. 信息真实义务：您必须提供真实、准确、完整且有效的身份信息及联系方式，并在\n信息发生变更后及时更新。因您提供的信息不真实、不准确或未及时更新而导致的\n任何损失或无法享受会员服务，由您自行承担。\n2. 合规使用义务：您承诺遵守中华人民共和国相关法律法规、本章程及凯撒旅游发布\n的所有会员规则。您不得从事任何非法、欺诈性或损害凯撒旅游利益的行为，包括\n但不限于：\n2.1.利用系统漏洞、技术手段或其他不正当方式恶意套取、刷取积分或权益；\n2.2.进行虚假交易、套现或协助他人套现；\n2.3.扰乱、攻击、干扰或破坏会员系统的正常运营秩序；\n2.4.将账户、积分或权益用于任何商业性或非个人消费用途。\n3. 责任承担义务：您应对您的会员账户下的一切活动（包括授权他人使用您的账户进\n行的操作）承担全部法律责任。如您的行为违反本章程，凯撒旅游有权单方采取包\n括但不限于警告、冻结积分、冻结会员账户、清零积分、降级乃至终止会员资格等\n措施，且无需因此向您承担任何责任。如您的行为给凯撒旅游造成损失，凯撒旅游\n保留追究您法律责任的权利。\n4. 您应自觉维护凯撒旅游及凯撒会员的声誉和形象，不在任何公共场所发布有损凯撒\n旅游和凯撒会员声誉的言论。\n5. 在未经凯撒旅游允许的情况下，严禁任何会员以凯撒旅游或凯撒会员的名义，组织\n和策划各类活动，由此引起的所有法律后果，将由当事人自负。一旦发现，凯撒旅\n游将依法追究其责任。\n\n第六章 附则\n第十三条 凯撒旅游权利、规则修订\n1. 对有意违背本章程的会员，凯撒旅游有权拒绝其参加所组织的会员活动。\n2. 凯撒旅游有权取消损害凯撒旅游及凯撒旅游会员形象或声誉的会员之会员资格。\n3. 凯撒旅游认为会员因其个人因素或其他合理原因不适参加活动时，可劝阻会员，并\n有权拒绝会员参加相关会员活动。\n4. 凯撒旅游组织的会员活动为非盈利性质的自助活动，参加的会员须对自己的安全负\n责。凯撒旅游对于会员参加活动时因个人因素和不可抗力因素以及第三方原因造成\n的事故和伤害不负法律、经济和医疗责任；会员承诺如因个人因素和不可抗力因素\n以及第三方原因造成的事故和伤害，将不追究凯撒旅游的任何民事、经济和医疗责\n任。活动中发生意外事故，凯撒旅游有义务组织救援或调整计划，但不承担任何法\n律、经济和医疗责任。\n5. 凯撒旅游有权根据业务发展、法律法规变化及维护会员权益的需要，不时对本会员\n章程 （包括但不限于积分规则、 会员等级评定标准、 权益内容等） 进行修订、 增删。\n\n6. 修订内容将通过凯撒旅游官方网站、凯撒优选等官方渠道进行公示通知。该等修订\n自公示载明的生效日期起生效，若公示中未载明生效日期，则视为自公示发布之日\n起 7 日后生效。\n7. 若会员在修订生效后继续使用会员服务 （包括但不限于进行消费、 获取或使用积分、\n参与会员活动等） ， 即视为会员已充分阅读、 理解并同意接受修订后的章程约束。 若\n会员不同意相关修订，有权终止使用会员服务并申请注销会员账户。\n第十四条 解释权\n本章程的最终解释权及适用权归凯撒旅游所有。凯撒旅游有权根据法律法规及本章\n程目的，对章程条款的含义及适用进行解释，相关解释应以符合凯撒旅游会员计划\n的初衷和公平合理原则为前提。\n第十五条 生效与适用\n1. 本章程自2025 年 9 月1 日起实施。\n2. 本章程生效前已获取的积分，其有效期按照原规则执行。本章程生效前已取得的会\n员等级，其有效期将按本章程第六条规定重新计算。\n3. 本章程构成会员与凯撒旅游之间关于会员计划的完整协议，并取代所有先前的口头\n或书面约定。\n4. 若本章程的任何条款被有管辖权的法院认定为无效或不可执行，则该条款应自该等\n认定之日起失效，但不影响本章程其余条款的持续有效性和执行效力。\n\n附录：常见问题说明（FAQ）\n 一、 关于会员注册与等级\n1. 问：如何成为会员？注册用户和会员有什么区别？\n答：完成手机号注册即为“注册用户”。注册用户通过凯撒旅游官方渠道完成首笔\n消费且订单行程回团或产品核销后，将自动升级为“会员”，开始享受积分和等级\n权益。注册用户仅可浏览产品，无法享受会员权益。\n2. 问：我的会员等级何时更新？\n答： 您的会员等级将于每月1 日系统自动重新计算您近12 个月的累计消费金额后更\n新。\n3. 问：为什么我消费后会员等级没有立刻提升？\n答： 您的会员等级并非实时更新。 系统会在每月 1 日统一评估所有会员近12 个月的\n累计消费金额，并据此更新等级。您在本月产生的消费，将在次月1 日后的新等级\n中体现。\n4. 问：我的会员等级有效期是如何计算的？\n答：银卡及以上等级有效期为1 年。有效期并非从您升级当天计算，而是从您达成\n或维持该等级的次月 1 日起计算， 至次年同日的前一日止。 例如， 您在3 月 15 日升\n级为金卡，您的金卡有效期将从4 月1 日开始计算。\n二、 关于积分获取与使用\n1. 问：消费金额是如何计算的？\n答：消费金额指订单的实际实付金额。不同类型产品的计入时间不同：旅游套餐、\n\n跟团游按行程结束回团之日计入；酒店、机票、门票、签证等按实际使用或核销之\n日计入。\n2. 问：积分为什么不是付款后立刻到账？\n答： 为确保积分准确发放， 积分需在您体验完服务后到账。 旅游套餐需回团后到账，\n酒店、 机票等需实际使用或核销后到账， 以防订单发生变更或退款， 请您耐心等待。\n3. 问：如果因系统问题导致积分丢失怎么办？\n答：若疑似因系统问题导致积分记录错误，请您保留相关消费凭证，并通过客服渠\n道联系我们。核实无误后，我们将按规则为您补发积分。\n4. 问：积分何时会失效？\n答：积分自获取之日起730 天内有效。系统将按“先进先出”（FIFO）原则自动管\n理积分有效期，到期积分将自动清零。\n5. 问：使用积分支付后，订单发生退款怎么办？\n答：订单若发生退款，已消耗的积分将不予退还，退款金额将为您实际支付的现金\n部分。请您在下单并使用积分前确认需求。\n6. 问：积分可以给家人朋友使用吗？\n答：很抱歉，积分与您的会员账户绑定，仅限本人使用，不可转让、不可赠与。但\n您可以为家人朋友代下单并使用积分抵扣。\n三、 关于权益享受\n1. 问：如何参与会员专属活动？\n答：我们会根据您的会员等级，通过短信、小程序消息等渠道定向邀请您参与适合\n您等级的专属活动。活动名额可能有限，请以收到邀请为准。\n2. 问：兑换第三方权益（如航空里程）需要注意什么？\n答：第三方权益的预约、获取及服务质量均由合作的第三方机构全权负责，请您在\n使用前仔细阅读并同意第三方的具体规则。凯撒旅游仅提供对接服务，不对其可用\n性及质量承担保证责任。\n3. 问：第三方权益（如机场贵宾厅）无法使用怎么办？\n答：请您首先核对是否满足合作方的使用规则 （如预约流程、开放时间等） 。 若问题\n仍未解决，请联系凯撒客服，我们将协助您与对方沟通，但最终解决责任在于权益\n提供方。\n四、 账户与安全\n1. 问：如何保护我的账户安全？\n答： 请妥善保管您的登录密码及短信验证码， 切勿告知他人。 建议您定期修改密码。\n如发现账户异常，请立即联系客服冻结账户。\n2. 问：手机号注销/换号了，如何变更绑定信息？\n答：为保证账户安全，如需更改绑定手机号，请您及时联系客服人员进行身份验证\n后，由客服协助您完成换绑操作，避免您的损失。\n3. 问：为什么我的账户/积分被冻结或清空了？\n答：如果您存在涉嫌刷单、套现、利用漏洞等违反本章程的行为，经系统监测与人\n工核实后，我们有权根据违规情节采取冻结、清零积分甚至冻结账户等措施。详情\n可咨询客服。\n五、 其他\n1. 问：对企业客户是否有不同的会员计划？\n答：目前本章程适用于个人会员。企业客户如有批量采购或定制服务需求，请联系\n我们的企业客户部，我们将为您提供专属解决方案。";
const CHARTER_CURRENT="凯撒旅游会员管理章程\n第一章 总则\n第一条 目的与适用范围\n为感谢每一位选择凯撒旅游的会员，提升会员的服务体验、 促进跨业务消费， 整合凯撒旅游\n集团用户资源， 以积分和权益为核心构建会员体系， 规范会员服务管理， 特制定本章程。 本\n章程适用于所有凯撒旅游会员及使用积分、 权益的用户，旨在为尊敬的会员提供系统性的尊\n享服务指南。请您注册用户或会员，且在使用用户或会员服务前，仔细阅读并理解本章程，\n您的注册、绑定、消费行为视为对本章程内容的理解与接受。\n第二条 定义\n1. 凯撒旅游：指北京凯撒国际旅行社有限责任公司及其旗下直接或间接提供旅游相关\n产品与服务的子公司、分公司、分支机构或关联公司（包括但不限于北京凯撒晟和\n国际旅行社有限公司、北京凯撒亿步国际旅行社有限公司等）的统称。本章程项下\n的会员服务、积分及权益，可能由上述任一主体或多家主体共同提供，相关权利义\n务由实际提供服务的法律主体承担。\n2. 凯撒优选：指由凯撒旅游提供技术支持和运营服务的微信小程序，本章程中提及的\n会员注册、积分获取与使用、权益兑换等行为，均通过该平台进行。\n3. 通通游平台：是凯撒旅游自建并拥有的用于凯撒旅游零售业务、门店业务和供应链\n业务的综合性业务管理系统。\n4. 注册用户：指已在凯撒优选完成手机号验证绑定但尚未进行首次消费的“凯撒优选”\n平台用户。注册用户可浏览平台内容，但无法享受会员积分、等级权益等服务。\n5. 会员（您）：指成功注册并接受本章程， 通过凯撒旅游官方渠道 （限于凯撒优选小程\n序、通通游平台）完成消费且订单对应行程已回团或产品已核销后获得会员身份，\n并依照本章程享有相应会员等级与专属权益的用户。\n6. 积分：指凯撒旅游为奖励会员消费与互动而授予的虚拟奖励工具，其功能、价值及\n有效期均由凯撒旅游单方设定， 具体规则以本章程及凯撒旅游的公布调整规则为准。\n积分可用于凯撒旅游指定的使用场景（如积分商城）兑换指定礼品、优惠券或抵扣\n部分消费金额，不可变现、不可转让、不可赠与，亦不得作为财产进行任何形式的\n交易或继承。凯撒旅游有权根据业务发展及法律法规要求，对积分获取与使用规则\n（包括但不限于积分价值、兑换比例、使用范围等）进行调整，具体以凯撒旅游实\n时公示标准为准。\n7. 权益：指凯撒旅游为不同等级会员提供的差异化优惠或权益服务，包括但不限于积\n分加速、会员专属活动、第三方合作权益等。所有权益均由凯撒旅游免费提供，其\n可获得性、种类、内容及质量可能因时间、地区、合作方情况等因素而变动。部分\n权益数量有限，兑完即止。涉及第三方提供的权益（以下简称“第三方权益”），其\n服务质量与责任由该第三方承担，凯撒旅游协助对接，不对此类权益的质量、可用\n性及任何争议承担保证或连带责任。\n消费金额：指会员通过凯撒旅游的官方渠道（限于凯撒优选、通通游平台）线上下\n单，购买凯撒旅游产品、 服务而实际支付的实付款项金额 （以人民币计算）； 会员如\n\n通过线下手工订单、定制团等非本章程确认的官方渠道或流程支付的订单，不参与\n会员积分与等级评定。旅行团产品消费金额按订单“回团”时间、酒店/机票/门票\n等标准化产品按“核销”时间计入相应会员等级统计周期，具体以本章程或凯撒旅\n游公布的规定为准。\n第三条 会员身份确认\n1. 用户通过凯撒优选小程序完成手机号验证绑定后，即成为注册用户。注册用户通过\n凯撒旅游官方渠道（包括凯撒优选小程序、通通游平台等）完成首笔消费实际接受\n凯撒旅游服务且订单对应行程已回团或产品已核销后，将自动升级为会员。会员身\n份及积分、权益仅授予实际支付订单的客户。\n2. 会员等级由低到高分为蓝卡、银卡、金卡、铂金卡、黑钻卡，仅依据会员近12 个月\n的累计消费金额进行动态评定，具体等级规则以本章程规定为准。\n\n第二章 会员等级与权益\n第四条 会员等级规则\n会员等级 注册用户 蓝卡 银卡 金卡 铂金卡 黑钻卡\n评定标准（年消费） 注册绑定 0-5 万元 5-10 万元 10-20 万元 20-40 万元 ≥40 万元\n基础权益 积分加速 - - 1.5 倍 1.8 倍 2 倍 3 倍\n活动特权 会员活动 - 1 次/年 2 次/年 5 次/年 8 次/年 12 次/年\n注：\n1. 消费金额指订单实际实付金额，旅行产品按回团时间、酒店机票等按核销时间计入\n（不含退费金额）。\n2. 积分加速倍数为在基础积分（消费金额的15%）之上的加速系数。\n第五条 等级权益细则\n1. 积分及积分加速：会员消费可获得积分， 基础积分为消费金额的15%。 各等级会员按\n本章程第四条规定的加速倍数提升积分获取效率。 （示例：黑钻卡会员消费1 万元，\n可获得基础积分1500 积分 × 3.0 = 4500 积分） 。\n2. 活动特权：凯撒旅游将根据会员等级， 不定期定向蓝卡-黑钻卡会员发出邀请，会员\n可参与专属回馈活动 （如高端线路体验、 旅游主题沙龙等） 。 每年各等级会员可受邀\n参与的活动次数上限详见本章程第四条表内规定。\n3. 第三方权益：凯撒旅游可能会不定时为特定等级会员引入由第三方合作方（如航空\n公司、酒店集团、金融机构等）独立提供的增值服务或权益（如机场贵宾厅、客房\n升级、优先登机等） 。 该等权益是凯撒旅游为会员争取的免费、额外增值优惠，并非\n会员依据本章程所必然获得的、或由凯撒旅游直接提供的核心权益。\n3.1.责任限制：凯撒旅游仅作为第三方权益的信息的发布渠道，将会员引导至第三\n方权益。第三方权益的预约、获取、使用条件、服务质量、可用性及最终解释权均\n完全归属于相应的第三方合作方。\n3.2.非保证责任：凯撒旅游不对任何第三方权益的可用性、质量、有效性、安全性\n\n承担任何明示或默示的保证或担保责任。会员因使用或无法使用第三方权益而产生\n的任何争议、损失或损害，应直接与第三方合作方解决，凯撒旅游可提供必要协助\n但不承担任何直接或连带责任。\n3.3.变更与终止：第三方权益可能受名额、地域、时间等限制，并可能因合作方政\n策调整而随时变更、中止或终止，凯撒旅游无需为此单独通知每位会员。\n3.4.会员义务：会员在申请和使用第三方权益前，应自行查阅并同意该第三方合作\n方的具体要求、条款与条件及隐私政策。会员在使用第三方权益时，其行为应同时\n遵守本章程及第三方合作方的规则。\n第六条 等级变更说明：\n1. 升级：系统将实时跟踪会员的累计消费金额。 当会员近12 个月累计消费金额达到更\n高等级标准时，系统将在满足条件后实时为其升级至对应会员等级，并自升级之日起\n享受相应权益。\n2. 保级与降级：每月1 日， 系统将自动对所有会员近12 个月的累计消费金额进行一次\n重新评估，并据此更新会员等级。\n2.1.保级：若消费金额达到或维持当前等级标准，则等级保持不变。\n2.2.降级：若消费金额未达到维持当前等级标准，将降至符合条件的相应等级（有\n历史消费的会员最低降至蓝卡会员） 。\n3. 等级有效期：蓝卡会员永久有效，其他等级会员等级有效期为1 年（自等级达成或\n维持的次月1 日起计算12 个自然月） ；有效期满后， 系统将立即根据您当时近 12 个\n月的累计消费金额，按照本条第2 款规则重新评定等级。\n\n第三章 积分获取与使用规则\n第七条 积分获取方式\n1. 消费积分：\n1.1.基础积分：会员每完成一笔有效消费，可按消费金额*15%计算获得基础积分值\n（例：消费1 万元获1500 积分），积分按四舍五入取整。\n1.2.等级加速积分：银卡、金卡、铂金卡、黑钻卡会员在获取基础积分时，可分别\n享受 1.5 倍-3.0 倍不等的对应等级加速权益，具体以本章程第四条项下标准执行。\n2. 积分计算时间：积分将于消费订单所对应的行程回团或产品核销后，自动发放至会\n员账户。具体而言：\n2.1.旅游套餐、跟团游等产品，按行程结束回团之日起算；\n2.2.酒店、机票、门票、签证等产品，按实际使用或核销之日起算。\n2.3.其他：本章程未列明的其他产品或服务，其积分计算与发放时间将以凯撒旅游\n另行公示的规则为准。凯撒旅游有权根据产品、服务的特性及业务运营需要，合理\n确定积分的入账时间。\n3. 行为积分：会员可通过凯撒优选完成指定的互动行为 （如每日签到、 撰写产品评价、\n分享活动等） ， 可依据凯撒优选当时平台实时公示的规则额外获取积分。 凯撒旅游有\n权随时调整任务内容、积分奖励额度及活动规则，并于凯撒优选公示后生效。\n4. 促销活动积分：凯撒旅游可能在会员权益日、节假日等特定时期，不定期推出促销\n\n活动（如积分翻倍、额外赠分等） 。活动规则、适用范围及有效期以官方公告为准。\n此类活动可能设有积分获取上限或总额限制，先到先得，赠完即止。\n异常情况处理：所有积分的获取必须基于真实、合法的消费和会员互动行为。凯撒\n旅游有权对涉嫌刷单、套现、作弊等违规行为的积分获取进行调查，一经核实，有\n权扣除相应积分、冻结/注销/终止会员账户并追究相关法律责任。\n第八条 积分使用规则\n1. 使用场景\n会员可通过以下方式使用其积分：\n1.1. 抵扣消费： 会员在购买凯撒旅游自营及甄选旅游产品时， 可在支付环节使用积分抵扣\n部分订单金额。抵扣标准为：10 积分 = 1 元人民币。每笔订单可使用积分抵扣的金\n额最高不超过该订单金额的2%。\n1.2. 兑换权益： 会员可在凯撒优选的积分商城内， 使用积分兑换指定的商品、 服务\n或权益，包括但不限于旅行优惠券、实物礼品、第三方服务（如机场贵宾厅、航空\n里程等） 。具体兑换比例、库存及规则以积分商城实时公示为准。\n2. 限制条款\n积分使用须遵守以下限制：\n2.1. 通用限制：积分不可兑现、不可转让、不可赠与、不可继承，且仅可用于本章\n程及平台规则指定的场景。\n2.2. 范围限制：积分不可用于支付外采产品、保险、税费、以\n及其他明确标示不可使用积分的费用。\n2.3. 第三方权益： 兑换涉及第三方提供的商品或服务时， 其质量、 可用性及售后服\n务均由该第三方负责，凯撒旅游不承担任何法律责任。相关争议需会员直接与第三\n方解决。\n2.4. 异常使用：凯撒旅游有权监控积分使用行为， 对于涉嫌欺诈、套现、 作弊等异\n常使用行为，有权冻结积分、撤销交易、甚至冻结/注销会员账户。\n3. 积分有效期与清零\n3.1. 有效期：积分自获取之日起生效，有效期为2 年（即730 天）。\n3.2. 清零规则：积分逾期之日满将自动失效并清零（即，自获取积分之日起满730\n天之当日晚 23:59:59 失效）。系统将依据“先获取的积分先使用”的原则自动扣减\n相应积分。\n3.3. 退款处理： 若会员使用积分抵扣或兑换的订单发生全部或部分退款， 已消耗的\n积分将不予退还，退款金额仅为用户实际支付的现金部分。\n3.4. 失效通知： 凯撒旅游可提供积分到期提醒服务 （如通过小程序消息、 短信等） ，\n但此项服务并非凯撒旅游的法定义务，最终积分有效期以系统记录为准。\n\n第四章 会员服务与保障\n第九条 服务承诺\n1. 积分查询：会员可通过凯撒优选实时查询积分余额、获取与消耗明细、有效期等信\n息。\n\n2. 权益兑现：凯撒旅游将通过凯撒优选等官方渠道，确保会员等级权益与活动规则透\n明、公开。对于会员在权益兑现中提出的争议，凯撒旅游客服团队将争取在接到反\n馈后的48 小时内予以响应并启动处理流程。\n3. 数据安全：凯撒旅游将采取符合法律规定的合理途径保护会员的隐私信息，未经会\n员授权同意，不向任何第三方披露、泄露或出售其个人敏感信息，法律法规另有规\n定的除外。\n4. 服务可用性：凯撒旅游将尽力保障会员系统 7×24 小时稳定运行，但鉴于互联网服\n务的特殊性，对于因系统维护、升级、故障、不可抗力等原因导致的服务中断或延\n迟，凯撒旅游不承担相应责任，但将尽力提前公告或在事后予以说明。\n第十条 投诉与纠纷处理\n1. 反馈渠道： 会员可通过以下渠道就积分、 权益、 服务等问题进行咨询、 投诉或反馈：\n1.1.官方客服热线：400-606-66656；\n1.2.凯撒优选小程序在线客服；\n1.3.凯撒旅游线下服务中心；\n1.4.其他：凯撒旅游官方公布的反馈渠道。\n2. 处理流程：\n会员提出争议后，凯撒旅游会员运营部将首先进行核实。经核实，确因凯撒旅游原\n因导致的积分、权益或等级记录错误，将按本章程规则予以补发或修正。\n3. 处理时限：凯撒旅游高度重视会员的反馈， 并致力于在接到投诉后的48 小时内 （工\n作日）提供初步响应；请您理解，对于涉及复杂情况或需要多部门协查的争议，处\n理时间可能适当延长。对于因会员未能提供必要信息、节假日、系统故障、不可抗\n力或其他非因凯撒旅游主观故意或重大过失导致的程序延迟，凯撒旅游不承担相应\n责任。\n4. 最终决定权：所有争议的解决均须以本章程及凯撒旅游平台记录为准。凯撒旅游拥\n有对争议的最终解释与处理决定权。\n\n第五章 会员权利与义务\n第十一条 会员权利\n作为凯撒旅游会员，您享有以下权利：\n1. 公平获取权：在遵守本章程的前提下，公平地获得积分、晋升会员等级及兑换各项\n会员权益的资格。\n2. 知情与咨询权：有权要求凯撒旅游对本章程及会员规则不明确之处进行解释说明；\n有权就账户积分、等级记录异常等情况申请核查。\n3. 权益享受权：有权按照本章程规定享受相应会员等级对应的积分加速、专属活动等\n权益。\n4. 免责声明：所有积分及权益均为凯撒旅游授予会员的优惠与礼遇，并非您支付对价\n后必然获得的固定回报。凯撒旅游可根据业务发展、市场环境及法律法规变化，对\n积分价值、权益内容及规则进行单方调整，并在法律要求的范围内进行公示。因不\n可抗力、第三方原因或您自身原因导致权益无法实现的，凯撒旅游不承担责任。\n\n5. 会员参加凯撒旅游举办的各种沙龙活动或其他联谊、信息交流等活动均采取自愿的\n原则。\n第十二条 会员义务\n作为凯撒旅游会员，您应履行以下义务：\n1. 信息真实义务：您必须提供真实、准确、完整且有效的身份信息及联系方式，并在\n信息发生变更后及时更新。因您提供的信息不真实、不准确或未及时更新而导致的\n任何损失或无法享受会员服务，由您自行承担。\n2. 合规使用义务：您承诺遵守中华人民共和国相关法律法规、本章程及凯撒旅游发布\n的所有会员规则。您不得从事任何非法、欺诈性或损害凯撒旅游利益的行为，包括\n但不限于：\n2.1.利用系统漏洞、技术手段或其他不正当方式恶意套取、刷取积分或权益；\n2.2.进行虚假交易、套现或协助他人套现；\n2.3.扰乱、攻击、干扰或破坏会员系统的正常运营秩序；\n2.4.将账户、积分或权益用于任何商业性或非个人消费用途。\n3. 责任承担义务：您应对您的会员账户下的一切活动（包括授权他人使用您的账户进\n行的操作）承担全部法律责任。如您的行为违反本章程，凯撒旅游有权单方采取包\n括但不限于警告、冻结积分、冻结会员账户、清零积分、降级乃至终止会员资格等\n措施，且无需因此向您承担任何责任。如您的行为给凯撒旅游造成损失，凯撒旅游\n保留追究您法律责任的权利。\n4. 您应自觉维护凯撒旅游及凯撒会员的声誉和形象，不在任何公共场所发布有损凯撒\n旅游和凯撒会员声誉的言论。\n5. 在未经凯撒旅游允许的情况下，严禁任何会员以凯撒旅游或凯撒会员的名义，组织\n和策划各类活动，由此引起的所有法律后果，将由当事人自负。一旦发现，凯撒旅\n游将依法追究其责任。\n\n第六章 附则\n第十三条 凯撒旅游权利、规则修订\n1. 对有意违背本章程的会员，凯撒旅游有权拒绝其参加所组织的会员活动。\n2. 凯撒旅游有权取消损害凯撒旅游及凯撒旅游会员形象或声誉的会员之会员资格。\n3. 凯撒旅游认为会员因其个人因素或其他合理原因不适参加活动时，可劝阻会员，并\n有权拒绝会员参加相关会员活动。\n4. 凯撒旅游组织的会员活动为非盈利性质的自助活动，参加的会员须对自己的安全负\n责。凯撒旅游对于会员参加活动时因个人因素和不可抗力因素以及第三方原因造成\n的事故和伤害不负法律、经济和医疗责任；会员承诺如因个人因素和不可抗力因素\n以及第三方原因造成的事故和伤害，将不追究凯撒旅游的任何民事、经济和医疗责\n任。活动中发生意外事故，凯撒旅游有义务组织救援或调整计划，但不承担任何法\n律、经济和医疗责任。\n5. 凯撒旅游有权根据业务发展、法律法规变化及维护会员权益的需要，不时对本会员\n章程 （包括但不限于积分规则、 会员等级评定标准、 权益内容等） 进行修订、 增删。\n\n6. 修订内容将通过凯撒旅游官方网站、凯撒优选等官方渠道进行公示通知。该等修订\n自公示载明的生效日期起生效，若公示中未载明生效日期，则视为自公示发布之日\n起 7 日后生效。\n7. 若会员在修订生效后继续使用会员服务 （包括但不限于进行消费、 获取或使用积分、\n参与会员活动等） ， 即视为会员已充分阅读、 理解并同意接受修订后的章程约束。 若\n会员不同意相关修订，有权终止使用会员服务并申请注销会员账户。\n第十四条 解释权\n本章程的最终解释权及适用权归凯撒旅游所有。凯撒旅游有权根据法律法规及本章\n程目的，对章程条款的含义及适用进行解释，相关解释应以符合凯撒旅游会员计划\n的初衷和公平合理原则为前提。\n第十五条 生效与适用\n1. 本原型规则整合版本的模拟生效日期为2026年10月1日。\n2. 本章程生效前已获取的积分，其有效期按照原规则执行。本章程生效前已取得的会\n员等级，其有效期将按本章程第六条规定重新计算。\n3. 本章程构成会员与凯撒旅游之间关于会员计划的完整协议，并取代所有先前的口头\n或书面约定。\n4. 若本章程的任何条款被有管辖权的法院认定为无效或不可执行，则该条款应自该等\n认定之日起失效，但不影响本章程其余条款的持续有效性和执行效力。\n\n附录：常见问题说明（FAQ）\n 一、 关于会员注册与等级\n1. 问：如何成为会员？注册用户和会员有什么区别？\n答：完成手机号注册即为“注册用户”。注册用户通过凯撒旅游官方渠道完成首笔\n消费且订单行程回团或产品核销后，将自动升级为“会员”，开始享受积分和等级\n权益。注册用户仅可浏览产品，无法享受会员权益。\n2. 问：我的会员等级何时更新？\n答： 您的会员等级支持消费达标后实时升级；每月1日重新评估近12个月累计消费金额，办理保级与降级。\n3. 问：为什么我消费后会员等级没有立刻提升？\n答： 消费达标后由实时升级任务处理；如暂未升级，请先核对订单是否已经回团或核销，以及实际付款主体。每月1日另执行全量评级。\n4. 问：我的会员等级有效期是如何计算的？\n答：银卡及以上等级有效期为1 年。有效期并非从您升级当天计算，而是从您达成\n或维持该等级的次月 1 日起计算， 至次年同日的前一日止。 例如， 您在3 月 15 日升\n级为金卡，您的金卡有效期将从4 月1 日开始计算。\n二、 关于积分获取与使用\n1. 问：消费金额是如何计算的？\n答：消费金额指订单的实际实付金额。不同类型产品的计入时间不同：旅游套餐、\n\n跟团游按行程结束回团之日计入；酒店、机票、门票、签证等按实际使用或核销之\n日计入。\n2. 问：积分为什么不是付款后立刻到账？\n答： 为确保积分准确发放， 积分需在您体验完服务后到账。 旅游套餐需回团后到账，\n酒店、 机票等需实际使用或核销后到账， 以防订单发生变更或退款， 请您耐心等待。\n3. 问：如果因系统问题导致积分丢失怎么办？\n答：若疑似因系统问题导致积分记录错误，请您保留相关消费凭证，并通过客服渠\n道联系我们。核实无误后，我们将按规则为您补发积分。\n4. 问：积分何时会失效？\n答：积分自获取之日起730 天内有效。系统将按“先进先出”（FIFO）原则自动管\n理积分有效期，到期积分将自动清零。\n5. 问：使用积分支付后，订单发生退款怎么办？\n答：订单若发生退款，已消耗的积分将不予退还，退款金额将为您实际支付的现金\n部分。请您在下单并使用积分前确认需求。\n6. 问：积分可以给家人朋友使用吗？\n答：很抱歉，积分与您的会员账户绑定，仅限本人使用，不可转让、不可赠与。但\n您可以为家人朋友代下单并使用积分抵扣。\n三、 关于权益享受\n1. 问：如何参与会员专属活动？\n答：我们会根据您的会员等级，通过短信、小程序消息等渠道定向邀请您参与适合\n您等级的专属活动。活动名额可能有限，请以收到邀请为准。\n2. 问：兑换第三方权益（如航空里程）需要注意什么？\n答：第三方权益的预约、获取及服务质量均由合作的第三方机构全权负责，请您在\n使用前仔细阅读并同意第三方的具体规则。凯撒旅游仅提供对接服务，不对其可用\n性及质量承担保证责任。\n3. 问：第三方权益（如机场贵宾厅）无法使用怎么办？\n答：请您首先核对是否满足合作方的使用规则 （如预约流程、开放时间等） 。 若问题\n仍未解决，请联系凯撒客服，我们将协助您与对方沟通，但最终解决责任在于权益\n提供方。\n四、 账户与安全\n1. 问：如何保护我的账户安全？\n答： 请妥善保管您的登录密码及短信验证码， 切勿告知他人。 建议您定期修改密码。\n如发现账户异常，请立即联系客服冻结账户。\n2. 问：手机号注销/换号了，如何变更绑定信息？\n答：为保证账户安全，如需更改绑定手机号，请您及时联系客服人员进行身份验证\n后，由客服协助您完成换绑操作，避免您的损失。\n3. 问：为什么我的账户/积分被冻结或清空了？\n答：如果您存在涉嫌刷单、套现、利用漏洞等违反本章程的行为，经系统监测与人\n工核实后，我们有权根据违规情节采取冻结、清零积分甚至冻结账户等措施。详情\n可咨询客服。\n五、 其他\n1. 问：对企业客户是否有不同的会员计划？\n答：目前本章程适用于个人会员。企业客户如有批量采购或定制服务需求，请联系\n我们的企业客户部，我们将为您提供专属解决方案。";
